import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { REDIRECT_301 } from '../src/config/redirect-map.mjs';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = path.join(root, 'public', '_redirects');

const staticRules = [...REDIRECT_301.entries()]
  .filter(([from, to]) => from !== to && !from.includes('*') && !to.includes('*') && !from.includes('://') && !to.includes('://'))
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([from, to]) => `${from}  ${to}  301`);

const lines = [
  '# Generated by scripts/write-redirects.mjs — edit redirect-map.mjs instead.',
  '# Static exact paths only. Host and checkout redirects run in the worker.',
  '# A splat or absolute URL here makes every later rule count as dynamic (limit 100).',
  ...staticRules,
  '',
];

fs.writeFileSync(out, `${lines.join('\n')}\n`, 'utf8');
console.log(`write-redirects: ${REDIRECT_301.size} 301 rules → public/_redirects`);
